// Send gate for the assistant's push notifications.
//
// Promo policy: at most 3 promos per customer per local calendar day
// (midnight to midnight in the customer's own time zone), and at least
// 2 hours between two promos to the same customer.
// Security alerts are never limited and never counted toward the promo limits.
//
// request() is permission and send in one step: an allowed promo is recorded
// immediately. cancel(id) removes that record when the provider reports the
// push never left, so it no longer uses up the daily cap or the 2-hour gap.

import { randomUUID } from 'node:crypto';

const DAILY_PROMO_CAP = 3;
const MIN_PROMO_GAP_MS = 2 * 60 * 60 * 1000;
// Local days differ from UTC days by at most 14 hours, and the gap rule looks
// back 2 hours. Records older than this can no longer affect any decision.
const RETAIN_MS = 48 * 60 * 60 * 1000;

const formatters = new Map();

function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Calendar date of `date` in `timeZone`, e.g. "2026-03-08". Throws RangeError
// for an unknown time zone.
function localDay(date, timeZone) {
  const parts = formatterFor(timeZone).formatToParts(date);
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

export function createGate() {
  // userId -> array of { id, time (ms), timeZone } for allowed promos
  const promosByUser = new Map();
  // id -> userId, for cancel()
  const ownerById = new Map();

  const deny = (rule) => ({ allowed: false, rule, id: null });

  function forget(userId, record) {
    ownerById.delete(record.id);
    const list = promosByUser.get(userId);
    if (!list) return;
    const i = list.indexOf(record);
    if (i !== -1) list.splice(i, 1);
    if (list.length === 0) promosByUser.delete(userId);
  }

  function prune(userId, nowMs) {
    const list = promosByUser.get(userId);
    if (!list) return;
    for (const record of [...list]) {
      if (record.time < nowMs - RETAIN_MS) forget(userId, record);
    }
  }

  function request({ userId, timeZone, category, now }) {
    if (category === 'security') {
      return { allowed: true, rule: '', id: randomUUID() };
    }
    if (category !== 'promo') return deny('unknown-category');

    const nowMs = now instanceof Date ? now.getTime() : NaN;
    if (Number.isNaN(nowMs)) return deny('invalid-time');

    let today;
    try {
      today = localDay(now, timeZone);
    } catch {
      return deny('invalid-time-zone');
    }

    prune(userId, nowMs);
    const list = promosByUser.get(userId) ?? [];

    // Day is judged in the customer's current time zone; each earlier promo is
    // placed on that same calendar.
    const sentToday = list.filter((r) => localDay(new Date(r.time), timeZone) === today);
    if (sentToday.length >= DAILY_PROMO_CAP) return deny('daily-cap');

    if (list.some((r) => Math.abs(nowMs - r.time) < MIN_PROMO_GAP_MS)) {
      return deny('min-gap');
    }

    const record = { id: randomUUID(), time: nowMs };
    list.push(record);
    promosByUser.set(userId, list);
    ownerById.set(record.id, userId);
    return { allowed: true, rule: '', id: record.id };
  }

  function cancel(id) {
    const userId = ownerById.get(id);
    if (userId === undefined) return;
    const record = promosByUser.get(userId)?.find((r) => r.id === id);
    if (record) forget(userId, record);
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-inv-d2-3/bot.mjs';

const LA = 'America/Los_Angeles';
const t = (s) => new Date(s);
const req = (g, o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });

// cap of 3 and gap of 2h; LA is UTC-7 in July
{
  const g = createGate();
  assert.equal(req(g, { now: t('2026-07-01T17:00:00Z') }).allowed, true);
  const gap = req(g, { now: t('2026-07-01T18:59:59Z') });
  assert.deepEqual([gap.allowed, gap.rule, gap.id], [false, 'min-gap', null]);
  assert.equal(req(g, { now: t('2026-07-01T19:00:00Z') }).allowed, true);
  assert.equal(req(g, { now: t('2026-07-01T21:00:00Z') }).allowed, true);
  const cap = req(g, { now: t('2026-07-01T23:00:00Z') });
  assert.deepEqual([cap.allowed, cap.rule, cap.id], [false, 'daily-cap', null]);
  // security unaffected and not counted
  const s = g.request({ userId: 'u', timeZone: LA, category: 'security', now: t('2026-07-01T23:00:00Z') });
  assert.deepEqual([s.allowed, s.rule], [true, '']);
  assert.ok(s.id);
  // next local day (after 07:00Z July 2)
  assert.equal(req(g, { now: t('2026-07-02T07:30:00Z') }).allowed, true);
}

// day boundary is local midnight, not UTC: 06:59Z = 23:59 LA, 07:00Z = 00:00 LA next day
{
  const g = createGate();
  for (const s of ['2026-07-01T02:00:00Z', '2026-07-01T04:30:00Z', '2026-07-01T06:30:00Z']) {
    // 19:00, 21:30 (Jun 30), 23:30 (Jun 30) LA
    assert.equal(req(g, { now: t(s) }).allowed, true, s);
  }
  assert.equal(req(g, { now: t('2026-07-01T06:59:00Z') }).rule, 'min-gap');
  // 08:30Z = 01:30 LA Jul 1, new day, >2h after last
  assert.equal(req(g, { now: t('2026-07-01T08:30:00Z') }).allowed, true);
}

// same instant, different zones: Berlin is already on the next day
{
  const g = createGate();
  const b = (now) => g.request({ userId: 'b', timeZone: 'Europe/Berlin', category: 'promo', now });
  assert.equal(b(t('2026-07-01T08:00:00Z')).allowed, true);   // 10:00
  assert.equal(b(t('2026-07-01T10:00:00Z')).allowed, true);   // 12:00
  assert.equal(b(t('2026-07-01T12:00:00Z')).allowed, true);   // 14:00
  assert.equal(b(t('2026-07-01T14:00:00Z')).rule, 'daily-cap');
  assert.equal(b(t('2026-07-01T22:00:00Z')).allowed, true);   // 00:00 Jul 2 Berlin
}

// DST: America/New_York spring forward 2026-03-08 (day is 23h), still a clean calendar day
{
  const g = createGate();
  const n = (now) => g.request({ userId: 'n', timeZone: 'America/New_York', category: 'promo', now });
  assert.equal(n(t('2026-03-08T05:30:00Z')).allowed, true);  // 00:30 EST Mar 8
  assert.equal(n(t('2026-03-08T08:00:00Z')).allowed, true);  // 04:00 EDT
  assert.equal(n(t('2026-03-08T12:00:00Z')).allowed, true);  // 08:00 EDT
  assert.equal(n(t('2026-03-08T16:00:00Z')).rule, 'daily-cap');
  assert.equal(n(t('2026-03-09T04:00:00Z')).allowed, true);  // 00:00 EDT Mar 9
}

// cancel frees cap and gap; unknown/double cancel harmless
{
  const g = createGate();
  const a = req(g, { now: t('2026-07-01T17:00:00Z') });
  assert.equal(req(g, { now: t('2026-07-01T17:30:00Z') }).rule, 'min-gap');
  g.cancel(a.id);
  g.cancel(a.id);
  g.cancel('nope');
  assert.equal(g.cancel(undefined), undefined);
  assert.equal(req(g, { now: t('2026-07-01T17:30:00Z') }).allowed, true);

  const g2 = createGate();
  const ids = [];
  for (const s of ['17:00', '19:00', '21:00']) ids.push(req(g2, { now: t(`2026-07-01T${s}:00Z`) }).id);
  assert.equal(req(g2, { now: t('2026-07-01T23:00:00Z') }).rule, 'daily-cap');
  g2.cancel(ids[1]);
  assert.equal(req(g2, { now: t('2026-07-01T23:00:00Z') }).allowed, true);
}

// users are independent; denied requests are not recorded; bad input
{
  const g = createGate();
  assert.equal(g.request({ userId: 'x', timeZone: LA, category: 'promo', now: t('2026-07-01T17:00:00Z') }).allowed, true);
  assert.equal(g.request({ userId: 'y', timeZone: LA, category: 'promo', now: t('2026-07-01T17:00:00Z') }).allowed, true);
  g.request({ userId: 'x', timeZone: LA, category: 'promo', now: t('2026-07-01T17:10:00Z') }); // denied
  assert.equal(g.request({ userId: 'x', timeZone: LA, category: 'promo', now: t('2026-07-01T19:00:00Z') }).allowed, true);
  assert.equal(g.request({ userId: 'x', timeZone: 'Mars/Base', category: 'promo', now: t('2026-07-01T23:00:00Z') }).rule, 'invalid-time-zone');
  assert.equal(g.request({ userId: 'x', timeZone: LA, category: 'weird', now: new Date() }).allowed, false);
}
console.log('all checks passed');
